"""Small calculator helpers."""

import math

SCALE = 10


def add(a, b):
    # add two numbers
    # and return the sum
    tmp = a + b
    return tmp


def mul(a, b):
    tmp = a * b
    return tmp


def area(r):
    tmp = math.pi * r * r
    return round(tmp, 2)


def scale(x):
    return x * SCALE


def main():
    print(add(1, 2))
    print(mul(3, 4))
    print(area(2))
    print(scale(5))


if __name__ == "__main__":
    main()

