pub struct Point {
    pub x: i32,
    pub y: i32,
}

impl Point {
    pub fn new(x: i32, y: i32) -> Self {
        Point { x, y }
    }

    pub fn sum(&self) -> i32 {
        self.x + self.y
    }

    pub fn scaled(&self, k: i32) -> Point {
        Point { x: self.x * k, y: self.y * k }
    }
}

pub fn origin() -> Point {
    Point::new(0, 0)
}

pub fn far() -> Point {
    Point::new(100, 100)
}

pub fn manhattan(a: &Point, b: &Point) -> i32 {
    (a.x - b.x).abs() + (a.y - b.y).abs()
}

